#!/usr/bin/env node
/**
 * Generates translation JSON files for all supported EU locales.
 * Each locale is a deep-merged override on top of the English base.
 * Supported: en, de, fr, es, it, pl, nl, pt, cs, sv
 *
 * Run:  node scripts/gen-i18n.js
 */
const fs   = require("fs");
const path = require("path");

const OUT = path.join(__dirname, "../messages");
const en  = JSON.parse(fs.readFileSync(path.join(OUT, "en.json"), "utf8"));

/** Deep-merge override on top of base (English) */
function deep(base, over) {
  if (!over) return base;
  const r = { ...base };
  for (const k of Object.keys(over)) {
    const bv = base[k], ov = over[k];
    if (typeof ov === "object" && !Array.isArray(ov) && ov !== null &&
        typeof bv === "object" && bv !== null)
      r[k] = deep(bv, ov);
    else
      r[k] = ov;
  }
  return r;
}

