/* ─── Generate files ──────────────────────────────────────────────────────── */
for (const [code, over] of Object.entries(locales)) {
  const merged = deep(en, over);
  const outPath = path.join(OUT, `${code}.json`);
  fs.writeFileSync(outPath, JSON.stringify(merged, null, 2), "utf8");
  console.log(`✅  ${code}.json written (${Object.keys(merged).length} top-level keys)`);
}

